<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Under the Wave off Kanagawa &mdash; low poly</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Zen+Old+Mincho:wght@400;700&display=swap" rel="stylesheet">
<style>
  html,body{margin:0;height:100%;overflow:hidden;background:#e9dcbe}
  #cap{position:fixed;left:18px;bottom:14px;color:#123a6b;font-family:'Zen Old Mincho',serif;
       font-size:15px;letter-spacing:.06em;opacity:.85;pointer-events:none;
       text-shadow:0 1px 0 rgba(244,239,224,.6)}
  #cap small{display:block;font-size:11px;opacity:.7}
</style>
</head>
<body>
<div id="cap">神奈川沖浪裏 &mdash; Under the Wave off Kanagawa<small>after Hokusai &middot; low poly, built in code</small></div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

const P = { paper:0xe9dcbe, deep:0x123a6b, mid:0x1d4e89, light:0x2f6aa8,
            foam:0xf4efe0, hull:0xd8a06a, fuji:0x2c568c, grey:0x9a978f };

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.setSize(innerWidth,innerHeight);
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(P.paper);
scene.fog = new THREE.Fog(P.paper, 42, 95);

const camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, .1, 200);
camera.position.set(0, 7.5, 20.5);

scene.add(new THREE.HemisphereLight(0xf2e8cf, 0x1d4e89, 1.35));
const sun = new THREE.DirectionalLight(0xfff4dd, 1.4);
sun.position.set(-6, 12, 8);
scene.add(sun);
const fill = new THREE.DirectionalLight(0xf4efe0, .8);
fill.position.set(2, 3, 12);
scene.add(fill);

// ---------- sky plane with paper/grey gradient ----------
{
  const g = new THREE.PlaneGeometry(150, 70, 2, 40);
  const c = []; const top = new THREE.Color(P.paper), gr = new THREE.Color(P.grey), low = new THREE.Color(0xc9bfa6);
  const pos = g.attributes.position;
  for (let i=0;i<pos.count;i++){
    const y = pos.getY(i); let col;
    if (y > 12) col = top;
    else if (y > 2) col = gr.clone().lerp(top, (y-2)/10);
    else col = low.clone().lerp(gr, Math.max(0,(y+12)/14));
    c.push(col.r,col.g,col.b);
  }
  g.setAttribute('color', new THREE.Float32BufferAttribute(c,3));
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({vertexColors:true, fog:false}));
  m.position.set(0, 12, -48); scene.add(m);
}

// ---------- Mount Fuji ----------
{
  const g = new THREE.ConeGeometry(2.7, 3.1, 6);
  g.translate(0, 1.55, 0);
  const pos = g.attributes.position, c = [];
  const bl = new THREE.Color(P.fuji), wh = new THREE.Color(P.foam);
  for (let i=0;i<pos.count;i++){
    const x=pos.getX(i), y=pos.getY(i), z=pos.getZ(i);
    const th = Math.atan2(z,x), line = 1.55 + .28*Math.sin(th*3+1.3) + .12*Math.sin(th*7);
    const col = y > line ? wh : bl;
    c.push(col.r,col.g,col.b);
  }
  g.setAttribute('color', new THREE.Float32BufferAttribute(c,3));
  const fuji = new THREE.Mesh(g, new THREE.MeshLambertMaterial({vertexColors:true, flatShading:true}));
  fuji.position.set(7.5, -0.4, -27); scene.add(fuji);
}

// ---------- clouds (flat paper blobs) ----------
const clouds = [];
for (let i=0;i<6;i++){
  const m = new THREE.Mesh(new THREE.IcosahedronGeometry(2+Math.random()*2.5,0),
    new THREE.MeshBasicMaterial({color:0xf4ecd6, fog:false}));
  m.scale.set(1.8,.28,.6);
  m.position.set(-24+i*9+Math.random()*4, 16+Math.random()*5, -34);
  clouds.push(m); scene.add(m);
}

// ---------- sea grid ----------
const seaGeo = new THREE.PlaneGeometry(76, 50, 110, 72);
seaGeo.rotateX(-Math.PI/2);
seaGeo.setAttribute('color', new THREE.Float32BufferAttribute(new Float32Array(seaGeo.attributes.position.count*3),3));
const sea = new THREE.Mesh(seaGeo, new THREE.MeshLambertMaterial({vertexColors:true, flatShading:true}));
scene.add(sea);

